// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testRegression_property() public {
        address owner = address(this);
        address adr = address(0x1234);
        vm.deal(owner, 10 ether);
        vm.prank(owner);
        c.Command(adr, "");
        c = new MultiplicatorX3();
        vm.deal(owner, 5 ether);
        vm.prank(owner);
        c.Command{value: 1 ether}(adr, "");
        assertTrue(adr.balance == 1 ether);
    }
}
